async function installSources(l, label, options, noMcp = false) {
  if (l.length === 0) {
    console.log('No skills to install.')
    return
  }

  console.log(
    `\n📦 Installing ${l.length} skill(s)${label}:${label ? '\n' : ''}`,
  )

  if (options.dryRun) {
    for (const source of l) console.log(`   • ${source}`)
    console.log(`\n📋 [dry-run] Would install ${l.length} skill(s).\n`)
    return
  }

  const { installed: successCount, failed: failCount } =
    await installBundleSources(
      l,
      { yes: true, noMcp },
      {
        onStart: (source, index) =>
          console.log('   [%s/%s] %s', index + 1, l.length, source),
        onError: (source, error) =>
          console.error('   ❌ %s: %s', source, error?.message),
      },
    )

  console.log()

  if (failCount === 0) {
    console.log(`✅ All ${successCount} skill(s) installed successfully.`)
  } else {
    console.log(`⚠️  ${successCount} installed, ${failCount} failed.`)
    if (options.frozenLockfile)
      throw new Error('Some skills failed to install.')
  }
}
